package vn.covie.cart.api; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.covie.cart.api.dto.*; import vn.covie.cart.application.CartService; import vn.covie.shared.concurrency.VersionPrecondition;
@RestController @RequestMapping("/api/v1/me/carts")public class MeCartController{private final CartService carts;public MeCartController(CartService carts){this.carts=carts;}@GetMapping public List<CartResponse> list(){return carts.list();}@GetMapping("/{cartId}")public ResponseEntity<CartResponse> get(@PathVariable UUID cartId){var r=carts.get(cartId);return ResponseEntity.ok().eTag(VersionPrecondition.format(r.version())).body(r);}@PostMapping("/items")public ResponseEntity<CartResponse> add(@RequestBody AddCartItemRequest req){var r=carts.add(req);return ResponseEntity.status(201).eTag(VersionPrecondition.format(r.version())).body(r);}}
